"use strict";var DailyEarning=function(n){var t={initialize:function(){DailyEarning.initEvent()},initEvent:function(){n("#ProductId").on("change",function(){t.renderContent()});n("#base-currency").change(function(){t.renderContent()})},renderContent:function(){var i={monthDate:n("#MonthDate").val(),productId:n("#ProductId").val(),baseCurrency:n("#base-currency").val(),IsOnlyContent:!0};t.renderDailyEarning(i)},renderDailyEarning:function(t){n.ajax({type:"POST",data:JSON.stringify(t),dataType:"html",contentType:"application/json; charset=UTF-8",cache:!1,url:Site.resolveRelativeUrl("UserPanel/DailyEarning"),success:function(t){n("#dailyEarningContent").html(t)},beforeSend:function(){Site.showLoader()},complete:function(){Site.hideLoader()}})}};return t}(jQuery);DailyEarning.initialize();